mapper.sql:
WHERE promotionals.status > 0

    AND (
    promotionals.title LIKE CONCAT('%', #{filter.searchText}, '%')
    OR promotionals.description LIKE CONCAT('%', #{filter.searchText}, '%')
    )


    AND promotionals.start >= #{filter.dateFrom}


    AND promotionals.end <= #{filter.dateTo}

mapper.select:
SELECT



ORDER BY


        ${filter.orderBy}


        promotionals.id DESC



    LIMIT #{filter.page}, #{filter.rowsPerPage}

mapper.delete:
DELETE sub_details FROM promotional_sub_details AS sub_details
INNER JOIN promotional_details AS details ON details.id = sub_details.promotional_detail_id
WHERE details.promotional_id = #{promotionalId}
